class MythTVError(Exception):
    """
    Base exception for all MythTV API errors.
    """


class MythTVHTTPError(MythTVError):
    """
    Raised when the MythTV server returns a non-success HTTP status.
    """

    def __init__(self, status_code, message, response=None):
        self.status_code = status_code
        self.response = response
        super().__init__(f"MythTV HTTP {status_code}: {message}")


class MythTVAPIError(MythTVError):
    """
    Raised when the MythTV API returns invalid or unexpected data.
    """
```

