from urllib.parse import quote


class MythService:
    def __init__(self, client):
        self.client = client


class MythAPI(MythService):
    """
    Myth service endpoints.
    """

    def get_host_name(self):
        return self.client.get("Myth/GetHostName")

    def get_connection_info(self, pin=None):
        params = {}
        if pin is not None:
            params["Pin"] = pin
        return self.client.get("Myth/GetConnectionInfo", params=params)

    def get_setting(self, host_name=None, key=None, default=None):
        params = {}
        if host_name is not None:
            params["HostName"] = host_name
        if key is not None:
            params["Key"] = key
        if default is not None:
            params["Default"] = default
        return self.client.get("Myth/GetSetting", params=params)

    def put_setting(self, host_name, key, value):
        return self.client.post(
            "Myth/PutSetting",
            data={
                "HostName": host_name,
                "Key": key,
                "Value": value,
            },
        )

    def get_time_zone(self):
        return self.client.get("Myth/GetTimeZone")

    def get_status(self):
        return self.client.get("Myth/GetStatus")

    def get_backend_info(self):
        return self.client.get("Myth/GetBackendInfo")


class DvrAPI(MythService):
    """
    DVR service endpoints.
    """

    def get_recorded_list(
        self,
        start_index=None,
        count=None,
        descending=None,
        title_regexp=None,
        rec_group=None,
        storage_group=None,
    ):
        params = {}

        if start_index is not None:
            params["StartIndex"] = start_index
        if count is not None:
