        if title_regexp is not None:
            params["TitleRegExp"] = title_regexp
        if rec_group is not None:
            params["RecGroup"] = rec_group
        if storage_group is not None:
            params["StorageGroup"] = storage_group

        return self.client.get("Dvr/GetRecordedList", params=params)

    def get_recorded(self, chan_id, start_time):
        return self.client.get(
            "Dvr/GetRecorded",
            params={
                "ChanId": chan_id,
