class ContentAPI(MythService):
    """
    Content service endpoints.
    """

    def get_file(self, storage_group, file_name):
        return self.client.get_raw(
            "Content/GetFile",
            params={
                "StorageGroup": storage_group,
                "FileName": file_name,
            },
        )

    def download_file(self, storage_group, file_name, destination):
        response = self.client.get_stream(
            "Content/GetFile",
            params={
                "StorageGroup": storage_group,
                "FileName": file_name,
            },
        )

        with open(destination, "wb") as f:
            for chunk in response.iter_content(chunk_size=1024 * 1024):
                if chunk:
                    f.write(chunk)

        return destination

