## `mythtv_api/client.py`

```python
import json
from urllib.parse import urljoin

import requests

from .exceptions import MythTVHTTPError, MythTVAPIError
from .services import (
    MythAPI,
    DvrAPI,
    GuideAPI,
    ChannelAPI,
    ContentAPI,
    VideoAPI,
)


class MythTVClient:
    """
    Python client for the MythTV Services API.

    MythTV usually exposes its services API on port 6544.

    Example:

        from mythtv_api import MythTVClient

        myth = MythTVClient("192.168.1.20")
        print(myth.myth.get_host_name())
        recordings = myth.dvr.get_recorded_list()
    """

    def __init__(
        self,
        host,
        port=6544,
        scheme="http",
        username=None,
        password=None,
        timeout=30,
        verify_ssl=True,
        session=None,
    ):
        if host.startswith("http://") or host.startswith("https://"):
            base_url = host.rstrip("/")
        else:
            base_url = f"{scheme}://{host}:{port}"

        self.base_url = base_url.rstrip("/") + "/"
        self.timeout = timeout
        self.verify_ssl = verify_ssl

        self.session = session or requests.Session()

        if username is not None or password is not None:
            self.session.auth = (username, password)

        self.session.headers.update(
            {
                "Accept": "application/json",
                "User-Agent": "mythtv-api-python/0.1.0",
            }
        )

        self.myth = MythAPI(self)
        self.dvr = DvrAPI(self)
        self.guide = GuideAPI(self)
        self.channel = ChannelAPI(self)
        self.content = ContentAPI(self)
        self.video = VideoAPI(self)

    def build_url(self, endpoint):
        endpoint = endpoint.lstrip("/")
        return urljoin(self.base_url, endpoint)

    def request(
        self,
        method,
        endpoint,
        params=None,
        data=None,
        json_data=None,
        raw=False,
        stream=False,
        **kwargs,
    ):
        """
        Perform a request against a MythTV API endpoint.

        By default, `format=json` is added to query parameters to request JSON
        responses from MythTV.
        """
        url = self.build_url(endpoint)

        params = dict(params or {})

        if not raw:
            params.setdefault("format", "json")

        response = self.session.request(
            method=method.upper(),
            url=url,
            params=params,
            data=data,
            json=json_data,
            timeout=kwargs.pop("timeout", self.timeout),
            verify=kwargs.pop("verify", self.verify_ssl),
            stream=stream,
            **kwargs,
        )

        if not response.ok:
            raise MythTVHTTPError(
                response.status_code,
                response.text,
                response=response,
            )

        if raw or stream:
            return response

        return self._decode_json(response)

    def get(self, endpoint, params=None, **kwargs):
        return self.request(
            "GET",
            endpoint,
            params=params,
            **kwargs,
        )

    def post(self, endpoint, data=None, params=None, json_data=None, **kwargs):
        return self.request(
            "POST",
            endpoint,
            params=params,
            data=data,
            json_data=json_data,
            **kwargs,
        )

    def put(self, endpoint, data=None, params=None, json_data=None, **kwargs):
        return self.request(
            "PUT",
            endpoint,
            params=params,
            data=data,
            json_data=json_data,
            **kwargs,
        )

    def delete(self, endpoint, params=None, **kwargs):
        return self.request(
            "DELETE",
            endpoint,
            params=params,
            **kwargs,
        )

    def get_raw(self, endpoint, params=None, **kwargs):
        """
        Return a raw requests.Response object.

        Useful for binary endpoints such as images, recordings, and files.
        """
        return self.request(
            "GET",
            endpoint,
            params=params,
            raw=True,
            **kwargs,
        )

    def get_stream(self, endpoint, params=None, **kwargs):
        """
        Return a streaming requests.Response object.
        """
        return self.request(
            "GET",
            endpoint,
            params=params,
            raw=True,
            stream=True,
            **kwargs,
        )

    def call(self, service, method, params=None, http_method="GET"):
        """
        Call an arbitrary MythTV Services API endpoint.

        Example:

            myth.call("Dvr", "GetRecordedList")
            myth.call("Myth", "GetHostName")
        """
        endpoint = f"{service.strip('/')}/{method.strip('/')}"
        return self.request(http_method, endpoint, params=params)

    def _decode_json(self, response):
        try:
            return response.json()
        except json.JSONDecodeError as exc:
            raise MythTVAPIError(
                f"Expected JSON response but received: {response.text[:500]}"
            ) from exc

    def close(self):
        self.session.close()

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc, tb):
        self.close()
```

